function remember(before){if(!before)return;if(JSON.stringify(before)===JSON.stringify(scene))return;undoStack.push(before);if(undoStack.length>60)undoStack.shift();redoStack=[];updateHistory();}
function mutate(fn,rebuild=true){finishEdit();const before=clone(scene);fn();remember(before);changed(rebuild);}
function finishEdit(){if(editingBase){remember(editingBase);editingBase=null;}}
function beginEdit(){if(!editingBase)editingBase=clone(scene);}
function undo(){finishEdit();if(!undoStack.length)return;redoStack.push(clone(scene));scene=undoStack.pop();changed(true);toast('Undid last edit');}
function redo(){finishEdit();if(!redoStack.length)return;undoStack.push(clone(scene));scene=redoStack.pop();changed(true);toast('Redid last edit');}
function updateHistory(){$('undo').disabled=!undoStack.length;$('redo').disabled=!redoStack.length;}
