function renderList(){const list=$('scene-list');list.replaceChildren();if(!scene.objects.length){list.innerHTML='<div class="empty-state">'+icon('sphere')+'<strong>A blank field.</strong>Add your first primitive to begin.</div>';return;}
 scene.objects.forEach((o,ix)=>{const row=document.createElement('div');row.className='object-row'+(o.id===scene.selected?' selected':'')+(!o.visible?' hidden':'');row.draggable=true;row.dataset.id=o.id;row.setAttribute('role','listitem');row.innerHTML=`<button class="object-select" aria-label="Select ${esc(o.name)}" aria-pressed="${o.id===scene.selected}"><span class="object-shape">${icon(o.type)}</span><span style="min-width:0"><span class="object-name">${esc(o.name)}</span><span class="object-meta"><span class="op-sign">${ix===0?'•':esc(opSigns[o.operation])}</span>${ix===0?'Base field':esc(opNames[o.operation])}</span></span></button><button class="icon-btn eye" aria-label="${o.visible?'Hide':'Show'} ${esc(o.name)}" title="${o.visible?'Hide':'Show'}">${icon(o.visible?'eye':'eyeoff')}</button>`;
 row.querySelector('.object-select').onclick=()=>select(o.id);row.querySelector('.eye').onclick=()=>mutate(()=>o.visible=!o.visible);row.ondragstart=e=>{e.dataTransfer.setData('text/plain',String(o.id));e.dataTransfer.effectAllowed='move';};row.ondragover=e=>{e.preventDefault();row.classList.add('drag-over');};row.ondragleave=()=>row.classList.remove('drag-over');row.ondrop=e=>{e.preventDefault();row.classList.remove('drag-over');const id=Number(e.dataTransfer.getData('text/plain'));mutate(()=>{const from=scene.objects.findIndex(x=>x.id===id),to=scene.objects.findIndex(x=>x.id===o.id);if(from>=0&&to>=0){const [item]=scene.objects.splice(from,1);scene.objects.splice(to,0,item);}});};list.append(row);});
}
function nextId(){let id=Math.max(0,...scene.objects.map(o=>o.id))+1;if(id>1000000){id=1;while(scene.objects.some(o=>o.id===id))id++;}return id;}
function addObject(type){if(scene.objects.length>=32){toast('This scene has reached its 32-object limit.');return;}mutate(()=>{const o=C.makeObject(type,nextId());const count=scene.objects.filter(x=>x.type===type).length;if(count)o.name+=' '+(count+1);o.position=scene.objects.length?[.6,0,.25]:[0,0,0];if(type==='plane')o.position=[0,-1.4,0];scene.objects.push(o);scene.selected=o.id;});toggleAdd(false);toast(typeNames[type]+' added');}
function duplicate(){const o=selected();if(!o||scene.objects.length>=32)return;mutate(()=>{const copy=clone(o);copy.id=nextId();copy.name=(o.name+' copy').slice(0,80);copy.position[0]=clamp(copy.position[0]+.42,-100,100);scene.objects.splice(scene.objects.indexOf(o)+1,0,copy);scene.selected=copy.id;});toast('Object duplicated');}
function deleteObject(){const o=selected();if(!o)return;mutate(()=>{const i=scene.objects.indexOf(o);scene.objects.splice(i,1);scene.selected=scene.objects[Math.min(i,scene.objects.length-1)]?.id||null;});toast('Object deleted');}
function reorder(delta){const o=selected();if(!o)return;const i=scene.objects.indexOf(o),j=i+delta;if(j<0||j>=scene.objects.length)return;mutate(()=>{scene.objects.splice(i,1);scene.objects.splice(j,0,o);});toast('Composition order updated');}
function toggleAdd(open){const show=open??!$('add-menu').classList.contains('open');$('add-menu').classList.toggle('open',show);$('add-object').setAttribute('aria-expanded',show);}
function openDrawer(name){drawer=drawer===name?null:name;$('scene-panel').classList.toggle('open',drawer==='scene');$('inspector').classList.toggle('open',drawer==='inspector');$('drawer-shade').classList.toggle('open',!!drawer);toggleAdd(false);}
function closeDrawers(){drawer=null;$('scene-panel').classList.remove('open');$('inspector').classList.remove('open');$('drawer-shade').classList.remove('open');toggleAdd(false);}
function section(title,body,open=true){return `<details ${open?'open':''}><summary>${title}</summary><div class="section-content">${body}</div></details>`;}
function options(items,value){return items.map(([v,n])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(n)}</option>`).join('');}
function selectControl(label,prop,items,value,scope='object'){const id=(scope+'-'+prop).replace(/\./g,'-');return `<div class="control-row"><label for="${id}">${label}</label><select id="${id}" class="bind" data-scope="${scope}" data-prop="${prop}">${options(items,value)}</select></div>`;}
function numberControl(label,prop,value,min,max,step=.01,scope='object'){const id=(scope+'-'+prop).replace(/\./g,'-');return `<div class="control-row"><label for="${id}">${label}</label><input id="${id}" class="bind" type="number" data-scope="${scope}" data-prop="${prop}" min="${min}" max="${max}" step="${step}" value="${num(value,5)}"></div>`;}
function rangeControl(label,prop,value,min,max,step=.01,scope='object',digits=2){const id=(scope+'-'+prop).replace(/\./g,'-');return `<div class="property-label"><label for="${id}">${label}</label><span class="range-value" id="value-${id}">${Number(value).toFixed(digits)}</span></div><div class="range-row"><input id="${id}" class="bind" type="range" data-scope="${scope}" data-prop="${prop}" data-digits="${digits}" min="${min}" max="${max}" step="${step}" value="${value}"></div>`;}
function vectorControl(label,prop,value,min,max,step){return `<div class="property-label">${label}<span style="font:8px var(--mono);color:#686574">${prop==='rotation'?'DEG':prop==='scale'?'FACTOR':'WORLD'}</span></div><div class="vector">${value.map((v,i)=>`<label class="vector-field"><span>${'XYZ'[i]}</span><input class="bind" type="number" aria-label="${label} ${'XYZ'[i]}" data-scope="object" data-prop="${prop}.${i}" min="${min}" max="${max}" step="${step}" value="${num(v,4)}"></label>`).join('')}</div>`;}
function renderInspector(){const box=$('inspector-content'),scroll=box.scrollTop;const o=selected();$('inspector-actions').classList.toggle('hidden-section',tab==='render'||!o);
 if(tab==='object'&&!o){box.innerHTML='<div class="empty-state">'+icon('sphere')+'<strong>Select a surface.</strong>Click an object in the viewport or scene list to explore its field.</div>';return;}
 if(tab==='object'){
 let geom=selectControl('Primitive','type',C.TYPES.map(t=>[t,typeNames[t]]),o.type);
 if(['sphere','deformed'].includes(o.type))geom+=numberControl('Radius','size.0',o.size[0],.02,20);
 if(['box','roundedBox'].includes(o.type))geom+=vectorControl('Half extents','size',o.size,.02,20,.01);
 if(['cylinder','capsule'].includes(o.type))geom+=numberControl('Radius','size.0',o.size[0],.02,20)+numberControl(o.type==='capsule'?'Half segment':'Half height','size.1',o.size[1],.02,20);
 if(o.type==='torus')geom+=numberControl('Major radius','size.0',o.size[0],.02,20)+numberControl('Tube radius','size.1',o.size[1],.02,20);
 geom+=rangeControl('Rounding / offset','rounding',o.rounding,0,1,.01);
 if(o.type==='deformed')geom+=rangeControl('Deformation','deformation',o.deformation,0,.6,.01)+numberControl('Frequency','frequency',o.frequency,.1,12,.1)+'<p class="fine-print">Sinusoidal displacement with a conservative distance bound.</p>';
 const mat=o.material;
 let material=`<div class="material-preview"><div class="material-ball" id="material-ball" style="background:radial-gradient(circle at 32% 23%,#fff5,${mat.color} 42%,#2d2024 95%)"></div><div><strong id="material-preview-name">${matNames[mat.kind]}</strong><span>PROCEDURAL / NO TEXTURES</span></div></div>`+selectControl('Surface','material.kind',C.MATERIALS.map(t=>[t,matNames[t]]),mat.kind)+`<div class="control-row"><label for="material-color">Base color</label><div class="color-field"><input type="color" id="material-color" class="bind" data-scope="object" data-prop="material.color" value="${mat.color}" aria-label="Material color"><input type="text" id="material-hex" value="${mat.color}" aria-label="Material hex color" maxlength="7" spellcheck="false"></div></div><div class="swatch-row">${['#cd805f','#d8c6a9','#899ba9','#ac96c1','#87b0a5','#474956'].map(c=>`<button class="swatch" data-color="${c}" style="background:${c}" aria-label="Set color ${c}" title="${c}"></button>`).join('')}</div>`+rangeControl('Roughness','material.roughness',mat.roughness,.02,1,.01)+selectControl('Pattern','material.pattern',C.PATTERNS.map(p=>[p,p[0].toUpperCase()+p.slice(1)]),mat.pattern);
 if(mat.kind==='emissive')material+=rangeControl('Light intensity','material.emission',mat.emission,0,8,.1);
 if(mat.kind==='glass')material+=numberControl('Refraction index','material.ior',mat.ior,1,2.5,.01)+rangeControl('Surface opacity','material.opacity',mat.opacity,0,1,.01)+'<p class="fine-print">Fresnel reflection, field-measured thickness, and tinted transmission.</p>';
 box.innerHTML=`<div class="selection-summary"><div class="object-shape">${icon(o.type)}</div><div class="selection-text"><input id="object-name" aria-label="Object name" value="${esc(o.name)}" maxlength="80"><span>${typeNames[o.type]} &nbsp; / &nbsp; ID ${String(o.id).padStart(2,'0')}</span></div></div>`+section('COMPOSITION',selectControl('Operation','operation',C.OPS.map(p=>[p,opNames[p]]),o.operation)+(['smoothUnion','smoothSubtract'].includes(o.operation)?numberControl('Blend radius','smoothness',o.smoothness,.005,4,.01):'')+`<p class="fine-print">${scene.objects.filter(x=>x.visible)[0]?.id===o.id?'First visible object · this field seeds the stack.':o.operation==='subtract'?'Cuts this volume out of all preceding objects.':o.operation==='intersect'?'Keeps the volume shared with the preceding field.':'Combines with the field above this layer.'}</p>`)+section('TRANSFORM',vectorControl('Position','position',o.position,-100,100,.05)+vectorControl('Rotation','rotation',o.rotation,-36000,36000,1)+vectorControl('Scale','scale',o.scale,.02,20,.05)+`<button class="subtle-button" id="reset-transform">${icon('reset')}Reset transform</button>`)+section('GEOMETRY',geom)+section('MATERIAL',material)+section('REPETITION & MOTION',numberControl('Repeat rings','repeat',o.repeat,0,4,1)+(o.repeat?numberControl('Cell spacing','spacing',o.spacing,.2,10,.05):'')+selectControl('Animation','animation',[['none','Static'],['spin','Rotate Y'],['float','Float'],['pulse','Pulse scale']],o.animation)+'<p class="fine-print">Finite repetition in local X/Z. Use the timeline to inspect any moment.</p>',false);
 $('object-name').onfocus=beginEdit;$('object-name').oninput=e=>{beginEdit();o.name=e.target.value;renderList();changed();};$('object-name').onchange=()=>{if(!o.name.trim())o.name='Untitled object';$('object-name').value=o.name;finishEdit();renderList();changed();};
 $('reset-transform').onclick=()=>mutate(()=>{o.position=[0,0,0];o.rotation=[0,0,0];o.scale=[1,1,1];});
 $('material-hex').onfocus=beginEdit;$('material-hex').oninput=e=>{if(/^#[0-9a-f]{6}$/i.test(e.target.value)){beginEdit();o.material.color=e.target.value.toLowerCase();$('material-color').value=o.material.color;e.target.setCustomValidity('');updateMaterialPreview();changed();}else e.target.setCustomValidity('Enter a six-digit hex color, such as #cd805f.');};$('material-hex').onchange=e=>{if(!e.target.checkValidity()){e.target.value=o.material.color;e.target.setCustomValidity('');}finishEdit();};
 box.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>mutate(()=>o.material.color=b.dataset.color));
 }else{
 const s=scene.settings;box.innerHTML='<div class="section-title-card"><h2>Light, field & precision.</h2><p>Inspect the renderer. Fine-tune the balance between detail and speed.</p></div>'+section('VIEW & CAMERA',selectControl('View','mode',modes.map((n,i)=>[i,n]),s.mode,'settings')+rangeControl('Field of view','fov',s.fov,20,90,1,'settings',0)+rangeControl('Exposure','exposure',s.exposure,.1,4,.05,'settings')+selectControl('Atmosphere','background',[['warm','Warm studio'],['slate','Cool slate'],['night','After hours']],s.background,'settings')+'<div class="control-row"><label for="settings-grid">Ground grid</label><input id="settings-grid" class="bind" type="checkbox" data-scope="settings" data-prop="grid" '+(s.grid?'checked':'')+'></div>')+section('RAY MARCHING',selectControl('Resolution','resolution',[[.25,'25% · draft'],[.5,'50% · fast'],[.75,'75% · balanced'],[1,'100% · native'],[1.5,'150% · fine'],[2,'200% · supersample']],s.resolution,'settings')+rangeControl('Maximum steps','steps',s.steps,16,256,8,'settings',0)+numberControl('Hit epsilon','epsilon',s.epsilon,.0001,.05,.0001,'settings')+numberControl('Max distance','maxDistance',s.maxDistance,5,150,1,'settings')+'<p class="fine-print">Smaller epsilon resolves finer detail. Increase steps for thin or strongly deformed fields. Resolution includes device pixel ratio, capped at 2048 pixels per side.</p>')+section('LIGHT & SURFACES',selectControl('Soft shadows','shadows',[[0,'Off'],[12,'12 · fast'],[24,'24 · balanced'],[48,'48 · fine'],[64,'64 · ultra']],s.shadows,'settings')+selectControl('Occlusion','ao',[[0,'Off'],[2,'2 samples'],[4,'4 samples'],[6,'6 samples']],s.ao,'settings')+selectControl('Reflections','reflections',[[0,'Environment'],[1,'1 bounce'],[2,'2 bounces']],s.reflections,'settings')+'<p class="fine-print">Directional key light, ambient fill, soft field shadows, and ACES tone mapping. Reflections are a roughness-weighted approximation.</p>')+section('DISTANCE INSPECTION',selectControl('Slice normal','sliceAxis',[['x','X axis · YZ plane'],['y','Y axis · XZ plane'],['z','Z axis · XY plane']],s.sliceAxis,'settings')+rangeControl('Slice position','slicePosition',s.slicePosition,-4,4,.05,'settings')+numberControl('Slice range','sliceRange',s.sliceRange,1,20,.1,'settings')+'<p class="fine-print">Choose SDF slice above. Warm regions are inside; pale contour is the actual zero surface. Contours are spaced by 0.2 world units.</p>',s.mode===7)+section('ANIMATION',numberControl('Playback speed','speed',scene.animation.speed,.1,3,.1,'animation')+'<p class="fine-print">Each object has its own motion. Time is shared, paused on restore, and preserved with the scene.</p>',false);
 }
 bindControls();box.scrollTop=scroll;
}
function updateMaterialPreview(){const o=selected();if(!o)return;if($('material-ball'))$('material-ball').style.background=`radial-gradient(circle at 32% 23%,#fff5,${o.material.color} 42%,#2d2024 95%)`;if($('material-preview-name'))$('material-preview-name').textContent=matNames[o.material.kind];if($('material-hex')&&document.activeElement!==$('material-hex'))$('material-hex').value=o.material.color;}
function getTarget(scope){return scope==='settings'?scene.settings:scope==='animation'?scene.animation:selected();}
function setProperty(root,path,value){const parts=path.split('.');let node=root;for(let i=0;i<parts.length-1;i++)node=node[parts[i]];node[parts.at(-1)]=value;}
function bindControls(){document.querySelectorAll('#inspector-content .bind').forEach(el=>{const target=()=>getTarget(el.dataset.scope),prop=el.dataset.prop,isSelect=el.tagName==='SELECT',isCheck=el.type==='checkbox';
 const getValue=()=>isCheck?el.checked:(el.type==='number'||el.type==='range'||(isSelect&&el.dataset.scope==='settings'&&!['background','sliceAxis'].includes(prop)))?Number(el.value):el.value;
 const apply=()=>{const root=target();if(!root)return;let value=getValue();if(typeof value==='number'){if(el.value===''||!Number.isFinite(value))return;const min=Number(el.min||-Infinity),max=Number(el.max||Infinity);value=clamp(value,min,max);if(['repeat','steps','shadows','ao','reflections','mode'].includes(prop))value=Math.round(value);}
 if(prop==='type'&&root.type!==value){const fresh=C.makeObject(value);root.size=fresh.size;root.rounding=fresh.rounding;}
 setProperty(root,prop,value);if(el.type==='range'){const out=$('value-'+el.id);if(out)out.textContent=Number(value).toFixed(Number(el.dataset.digits||0));}
 if(prop==='material.color'){if($('material-hex'))$('material-hex').value=value;updateMaterialPreview();}changed();
 };
 if(isSelect||isCheck)el.onchange=()=>{const before=clone(scene);apply();remember(before);refresh();};
 else{el.onfocus=beginEdit;el.onpointerdown=beginEdit;el.oninput=()=>{beginEdit();apply();};el.onchange=()=>{finishEdit();if(el.type==='number'){const parts=prop.split('.');let val=target();for(const p of parts)val=val[p];el.value=num(val,5);}if(prop==='repeat'){const existing=document.querySelector('[data-prop="spacing"]')?.closest('.control-row');if(target().repeat&&!existing){el.closest('.control-row').insertAdjacentHTML('afterend',numberControl('Cell spacing','spacing',target().spacing,.2,10,.05));bindControls();}else if(!target().repeat&&existing)existing.remove();}};el.onblur=finishEdit;}
 });}
function setTab(name){finishEdit();tab=name;for(const t of ['object','render']){$('tab-'+t).classList.toggle('active',tab===t);$('tab-'+t).setAttribute('aria-selected',tab===t);}renderInspector();}
function setMode(m){mutate(()=>scene.settings.mode=Number(m),false);if(tab==='render')renderInspector();}
function setTool(t){tool=t;for(const [id,val]of [['orbit','orbit'],['move','translate'],['pan','pan']]){$('tool-'+id).classList.toggle('active',t===val);$('tool-'+id).setAttribute('aria-pressed',t===val);}$('viewport-canvas').classList.toggle('translate',t==='translate');$('gesture-hint').innerHTML=t==='translate'?'<kbd>DRAG</kbd> move in view plane <span style="margin:0 5px;opacity:.4">/</span> drag an axis to constrain':t==='pan'?'<kbd>DRAG</kbd> pan <span style="margin:0 5px;opacity:.4">/</span> scroll to zoom':'<kbd>DRAG</kbd> orbit <span style="margin:0 5px;opacity:.4">/</span><kbd>⇧</kbd> pan <span style="margin:0 5px;opacity:.4">/</span> scroll to zoom';updateGizmo();}
function project(point){const rect=$('viewport').getBoundingClientRect(),b=cameraBasis(scene.camera),v=vsub(point,b.pos),z=vdot(v,b.forward);if(z<.01)return null;const factor=rect.height/(2*Math.tan(scene.settings.fov*Math.PI/360)*z);return {x:rect.width*.5+vdot(v,b.right)*factor,y:rect.height*.5-vdot(v,b.up)*factor,z,factor};}
let gizmoAxes=[];
function updateGizmo(){const el=$('gizmo'),o=selected();gizmoAxes=[];if(!o||!o.visible||scene.settings.mode===7){el.innerHTML='';updateOrientation();return;}let pos=o.position.slice();if(o.animation==='float')pos[1]+=Math.sin(scene.animation.time*1.2+scene.objects.filter(o=>o.visible).indexOf(o))*.22;const p=project(pos);if(!p){el.innerHTML='';return;}const len=scene.camera.distance*.095,colors=['#ad6471','#70836b','#758bad'];let out='';
 for(let i=0;i<3;i++){const v=[0,0,0];v[i]=len;const end=project(vadd(pos,v));if(!end)continue;const dx=end.x-p.x,dy=end.y-p.y,screenLen=Math.hypot(dx,dy);if(screenLen<8)continue;gizmoAxes.push({axis:i,dx:dx/len,dy:dy/len});out+=`<g data-axis="${i}"><path d="M${p.x},${p.y}L${end.x},${end.y}" stroke="#fff9" stroke-width="4"/><path d="M${p.x},${p.y}L${end.x},${end.y}" stroke="${colors[i]}" stroke-width="2"/><path class="axis" data-axis="${i}" d="M${p.x},${p.y}L${end.x},${end.y}"/><circle class="handle" data-axis="${i}" cx="${end.x}" cy="${end.y}" r="5" fill="${colors[i]}" stroke="#f5ecea" stroke-width="1.5"/><text class="axis-label" x="${end.x+8}" y="${end.y+4}" fill="${colors[i]}">${'XYZ'[i]}</text></g>`;}
 out+=`<circle cx="${p.x}" cy="${p.y}" r="4" fill="#f4e9e1" stroke="#87729b" stroke-width="1.5"/>`;el.innerHTML=out;updateOrientation();}
function updateOrientation(){const b=cameraBasis(scene.camera),colors=['#b47880','#809278','#829bbd'];let html='<circle cx="29" cy="30" r="22" fill="#eee9e855" stroke="#fff3"/>';for(let i=0;i<3;i++){const axis=[0,0,0];axis[i]=1;const x=29+vdot(axis,b.right)*19,y=30-vdot(axis,b.up)*19;html+=`<path d="M29 30L${x} ${y}" stroke="${colors[i]}" stroke-width="1.5"/><circle cx="${x}" cy="${y}" r="3" fill="${colors[i]}"/><text x="${x+4}" y="${y+3}" fill="${colors[i]}" style="font:8px var(--mono);font-weight:600">${'XYZ'[i]}</text>`;}html+='<circle cx="29" cy="30" r="2.5" fill="#c3bcc6"/>';$('orientation').innerHTML=html;}
function resetCamera(){scene.camera=clone(makePreset(activePreset||'soft').camera);changed();toast('Camera reset');}
function focusSelected(){const o=selected();if(!o)return;scene.camera.target=o.position.slice();const r=Math.max(...o.size)*Math.max(...o.scale);scene.camera.distance=clamp(r*4.6,2,30);changed();toast('Focused '+o.name);}
